58	    private MvcResult postJson(String url, Map<String, Object> body, String actor, int expectedStatus)
59	            throws Exception {
60	        var request = post(url).contentType(MediaType.APPLICATION_JSON)
61	                .content(objectMapper.writeValueAsString(body));
62	        if (actor != null) {
63	            request = request.header("X-Actor-Id", actor);
64	        }
65	        return mvc.perform(request).andExpect(status().is(expectedStatus)).andReturn();
66	    }
