374	    @Test
375	    void twoSourcesRacingSameTargetSucceedAtMostOnce() throws Exception {
376	        long windowId = createWindow("ch-race-target-" + run, "20");
377	        String sourceA = submit(windowId, "user-a", "4", "alice");
378	        String sourceB = submit(windowId, "user-b", "4", "bob");
379	        String target = submit(windowId, "user-t", "4", "carol");
380	        approve(sourceA, 200);
381	        approve(sourceB, 200);
382	
383	        ExecutorService pool = Executors.newFixedThreadPool(2);
384	        CountDownLatch gate = new CountDownLatch(1);
385	        Future<Integer> f1 = pool.submit(() -> {
386	            gate.await();
387	            return transferStatus(key("tkc"), key("tk"), sourceA, target, "alice");
388	        });
389	        Future<Integer> f2 = pool.submit(() -> {
390	            gate.await();
391	            return transferStatus(key("tkc"), key("tk"), sourceB, target, "bob");
392	        });
393	        gate.countDown();
394	        int s1 = f1.get(30, TimeUnit.SECONDS);
395	        int s2 = f2.get(30, TimeUnit.SECONDS);
396	        pool.shutdown();
397	
398	        assertEquals(1, (s1 == 200 ? 1 : 0) + (s2 == 200 ? 1 : 0),
399	                "同一目标最多一次转让成功: " + s1 + "/" + s2);
400	        int conflict = (s1 == 409 ? 1 : 0) + (s2 == 409 ? 1 : 0);
401	        assertEquals(1, conflict);
402	        // 汇总不变：4 + 4（胜方 0、负方 4、目标 4）
403	        assertEquals("8", getOk("/api/windows/" + windowId + "/capacity").get("approvedTotal").asText());
404	        assertEquals(1, transfers(windowId).get("transfers").size());
405	        JsonNode targetNode = allocation(windowId, target);
406	        assertEquals("APPROVED", targetNode.get("status").asText());
407	        assertEquals("4", targetNode.get("heldAmount").asText());
408	    }
